\section*{49. --- Homomorphismes de $\mathcal{M}_{0,3}$, les groupes $\mathcal{M}_{g,\nu}$ profinis}\addcontentsline{toc}{section}{49. Homomorphismes de $\mathcal{M}_{0,3}$, les groupes $\mathcal{M}_{g,\nu}$ profinis}
\label{sec:49}
\section*{}

I) Considérons un sous-groupe $\mathcal{G}$ de $\mathcal{M}_{0,3}$, contenant $\mathcal{G}_{0,3}^+$, image réciproque d'un sous-groupe fini $\mathcal{G}_{0,3}^\sim$ de $\mathcal{M}_{0,3}^\sim$.\footnote{Toute cette section semble être la mise au point du résultat annoncé p.\ 333.} On suppose que celui-ci contient un sous-groupe -- disons qu'il contient un sous-groupe d'indice fini de $\Gamma \subset \Gamma_{0,3}$. Pour le simplifier, on pose $G = \operatorname{Ker} \varepsilon_3$. En résumant :
$$
\mathcal{G} \cap \mathcal{G}_{0,3}^+ \subset \mathcal{M}_{0,3}^\sim, \quad (\text{où } g \mapsto \text{prims} \equiv 1 \pmod 3) \leqno{(1)}
$$
Cette dernière hypothèse implique donc que pour tout $g \in \mathcal{G}$, $g_{\text{prim}} \in \mathcal{G}_{0,3}^\sim$, d'où
$$
g \xrightarrow{\sim} \underline{G}_{0,3}^\sim \leqno{(2)}
$$
En posant
$$
\begin{cases}
\mathcal{G}_{[0]} = \mathcal{G} \cap \mathcal{M}_{0,3}^\sim([0]) \\
\mathcal{G}_{[0],3} = \mathcal{G} \cap \mathcal{M}_{0,3}^+[0,3] = \operatorname{Norm}_{\mathcal{G}}(\mathcal{L}_0^\sim)
\end{cases} \leqno{(3)}
$$
On a aussi :
$$
\mathcal{G} = \mathcal{G}_{0} \cdot \mathcal{G}_0^+ \quad (\text{pour tout sous-divisé } [unclear: ...]) \leqno{(4)}
$$
$$
\mathcal{G}_{[0]} = \mathcal{G}_{0} \cdot \mathcal{L}_0^\sim \leqno{(5)}
$$
$$
\mathcal{G}_{[0],3} = \mathcal{G}_{0}^+ \cdot \mathcal{L}_0^\sim \leqno{(6)}
$$
On a posé
$$
\mathcal{L}_0^\sim = \text{sous-groupe fermé de } \mathcal{G}_{0,3}^{+\wedge} \text{ engendré par } [unclear: ...]
$$
à l'aide de $\mathcal{L}_0^\sim, \mathcal{L}_0^\sim$.

\chapter*{\S \space 49. --- HOMOMORPHISMES DE $M_{0,3}$, LES GROUPES $M_{g,r}$ GÉNÉRAUX}\thispagestyle{empty}

\begin{enumerate}
\item[I)] Considérons un sous-groupe fini $\mathcal{G}$ de $M_{0,3}$, contenu dans $\mathfrak{S}_{0,3}^{+\wedge}$, d'image dans un sous-groupe fini $\widetilde{\mathcal{G}}$ de $\widetilde{\mathfrak{S}}_{0,3}^\sim$. On suppose que celui-ci "s'affaisse"\footnote{Toute telle section sera dite antilinéaire, de même les automorphismes antilinéaires sur les groupes de Teichmüller cf. p. 333'--337'.} --- "gros" --- disons qu'il contient un sous-groupe d'indice fini de $\overline{\Gamma} \subset \overline{\Gamma}_{0,3}^\sim$. Pour la simplicité, on suppose pour simplifier que $\mathcal{G} \subset \Ker \varepsilon_3$. Cela signifie
$$
\mathcal{G} \isom \widetilde{\mathcal{G}} \subset \widetilde{M}_{0,3} \quad, \quad u \in \mathcal{G} \implies u \equiv 1 \pmod 3 \leqno{(1)}
$$
Cette deuxième hypothèse signifie donc que pour tout $u \in \mathcal{G}$,
$$
\mathcal{G} \xrightarrow{\quad u \mapsto \bar{u} \quad} \mathfrak{S}_{0,3}^+ \leqno{(2)}
$$
$$
\begin{cases} u(p) = \operatorname{int}(\bar{u}) \cdot p & d_0 = d_0 u \\ u(\sigma) = \operatorname{int}(\bar{u}) \cdot \sigma & \text{pour } u \in \mathcal{G} \end{cases} \leqno{(3')}
$$
On considère
$$
\begin{aligned}
\mathcal{G}_{(0)} &= \mathcal{G} \cap \widetilde{M}_{0,3}^\sim (0) \\
\mathcal{G}_{[0]} &= \mathcal{G} \cap \widetilde{M}_{0,3}^\sim [0] = \operatorname{Norm}_{\mathcal{G}}(L_0^\sim)
\end{aligned} \leqno{(3)}
$$
d'où suite
$$
\mathcal{G} = \mathcal{G}_{(0)} \cdot \mathfrak{S}_{0,3}^{+\wedge} \qquad \text{(qui est sous-direct)} \leqno{(4)}
$$
$$
\mathcal{G}_{[0]} = \mathcal{G}_{(0)} \cdot L_0^\sim \qquad \text{i.e.} \leqno{(5)}
$$
$$
\mathcal{G}_{[0]} \cap \mathfrak{S}_{0,3}^{+\wedge} = L_0^\sim \leqno{(6)}
$$
On a pour
$$
L_0^\sim = \text{sous-groupe fermé de } \mathfrak{S}_{0,3}^{+\wedge} \text{ engendré par } \mathcal{G}_{(0)}, L_0^\sim \leqno{(7)}
$$
et $d_0$ opère sur $\mathcal{G}_{(0)}$, $L_0^\sim$.
\end{enumerate}

\chapter*{\S \space 49. --- Homomorphismes de $\mathcal{M}_{0,3}$, les groupes $M_{g,0}$ généraux}\thispagestyle{empty}
\addcontentsline{toc}{section}{49. Homomorphismes de $\mathcal{M}_{0,3}$, les groupes $M_{g,0}$ généraux}
\label{sec:49}
\section*{}

I) Considérons un sous-groupe fermé $\mathcal{G}$ de $\mathcal{M}_{0,3}$, contenu\footnote{Tout celà vaut dans le contexte des sections / surjections pour le reste, mutatis mutandis, l'invariant $\delta_0$ étant \dots cf p. 333'.} dans $\mathfrak{S}_{0,3}^{+\wedge}$, i.e.\ image inverse d'un sous-groupe fermé de $\mathfrak{T}_{0,3}^\sim$. On suppose que celui-ci a ``suffisamment gros'' - disons qu'il contienne un sous-groupe d'indice fini de $\Gamma_{\mathbf{Q}} \subset \mathfrak{T}_{0,3}^\sim$. Pour le moment, on supposera pour simplifier que $\mathcal{G} \subset \Ker \varepsilon_3$. En résumé :
$$
\mathcal{G} \subset \mathfrak{S}_{0,3}^{+\wedge} \subset \mathcal{M}_{0,3}^\sim , \quad g \in \mathcal{G} \implies p(g) \equiv 1\ (3) \leqno{(1)}
$$
Cette dernière hypothèse signifie donc que pour tout $g \in \mathcal{G}$, $g = (\alpha_g, u_g) \in \mathfrak{S}_{0,3}^{+\wedge}$, dont la
$$
g \leftrightarrow (u_g, \alpha_g) \leqno{(2)}
$$
caractérisée par 
$$
\begin{cases} 
u(p) = \operatorname{int}(\alpha_0) p \\ 
u(s) = \operatorname{int}(\beta_0) s 
\end{cases} \quad \alpha_0 = \dots \leqno{(2')}
$$
On considère
$$
\mathcal{G}_{(0)} = \mathcal{G} \cap \mathcal{M}_{0,3}^\sim (0) \leqno{(3)}
$$
$$
\mathcal{G}_{[0]} = \mathcal{G} \cap \mathcal{M}_{0,3}^\sim [0] = \operatorname{Norm}_{\mathcal{G}} (L_0^\otimes)
$$
de sorte que 
$$
\mathcal{G} = \mathcal{G}_{(0)} \cdot \mathcal{G}_{[0]} \quad \text{(qui sont semi-directs)} \leqno{(4)}
$$
$$
\mathcal{G}_{[0]} = \mathcal{G}_{(0)} \cdot L_0^\otimes \leqno{(5)}
$$
$$
\mathcal{G}_{[0]} \cap \mathcal{G}_{(0)} = L_0^\otimes \leqno{(6)}
$$
Où on a posé 
$$
L_0^\otimes = \text{sous-groupe fermé de } \mathcal{G}_{0,3}^{+\wedge} \text{ engendré} \leqno{(7)}
$$
respectivement par $L_0^\otimes, L_0^\otimes$.
